#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *intToRoman(int num) {
    const int values[] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
    const char *symbols[] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

    char *result = (char *)malloc(32);
    if (result == NULL) return NULL;

    int pos = 0;
    result[0] = '\0';

    for (int i = 0; i < 13; i++) {
        while (num >= values[i]) {
            int len = (int)strlen(symbols[i]);
            memcpy(result + pos, symbols[i], (size_t)len);
            pos += len;
            result[pos] = '\0';
            num -= values[i];
        }
    }

    return result;
}

